R.append(T(2976,"सेब-दालचीनी वाला फ्लेवर्ड पानी","पानी किडनी के मरीज़ों के लिए सबसे सेहतमंद पेय पदार्थों में से एक है, लेकिन यह ज़रूरी नहीं कि वह सादा और बेस्वाद ही हो! DaVita की आहार विशेषज्ञ कारा की कई फ्लेवर्ड पानी रेसिपी में से एक, सेब-दालचीनी वाला फ्लेवर्ड पानी आज़माएँ।","10","1 कप (8 औंस)",
["10 कप पानी","1 मध्यम आकार का सेब","2 दालचीनी की डंडियाँ","2 छोटे चम्मच पिसी हुई दालचीनी"],
["बिना छीले सेब को पतले टुकड़ों में काटें।","सभी सामग्री एक जग में डालें।","परोसने से पहले रात भर फ्रिज में रखें।"],
["यदि आप तरल पदार्थ सीमित मात्रा में लेते हैं, तो अपनी ज़रूरत के अनुसार मात्रा को समायोजित करें।","स्वाद आ जाने के बाद आप इसे आइस क्यूब ट्रे में डालकर फ्लेवर्ड बर्फ बना सकते हैं।"],["कोई नहीं"]))
R.append(T(2977,"सेब और अजवाइन (सेलरी) के साथ टूना सलाद","टेक्सास की DaVita आहार विशेषज्ञ मटिल्डे समझती हैं कि भोजन आराम का प्रतीक होता है और सेहतमंद आहार अपनाना उनके मरीज़ों के लिए मुश्किल हो सकता है। इसीलिए मटिल्डे की कई खूबियों में से एक है परिवार की पसंदीदा, स्वादिष्ट और किडनी-अनुकूल रेसिपी साझा करना। सेब और सेलरी वाला यह टूना सलाद स्वादिष्ट, प्रोटीन से भरपूर और बनाने में आसान है।","4","टूना के कटोरे का 1/4 हिस्सा (लगभग 3/4 कप)",
["15 औंस डिब्बाबंद बिना नमक वाली टूना, पानी में पैक की हुई","1/2 बड़ा सेब","सेलरी का 1 डंठल","1/2 छोटा प्याज़","3 बड़े चम्मच मेयोनेज़","1/8 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच नमक (वैकल्पिक)"],
["टूना का पानी निथार लें और सेब, सेलरी तथा प्याज़ को बारीक काट लें।","एक मध्यम कटोरे में टूना, सेब, सेलरी, प्याज़, मेयोनेज़, काली मिर्च और नमक मिलाएँ।","सलाद के पत्तों की परत पर, बिना नमक वाले क्रैकर के साथ परोसें या सैंडविच बनाएँ।"],
["यदि आप कम प्रोटीन वाला आहार ले रहे हैं तो मात्रा को समायोजित करें। अपनी व्यक्तिगत ज़रूरतों के अनुसार सही मात्रा के लिए अपने आहार विशेषज्ञ से पूछें।","फलों और सब्ज़ियों का रस टूना सलाद में नमी बनाए रखेगा।","यदि आप कुछ कुरकुरा खाना चाहते हैं, तो मटिल्डे का टूना सलाद सेलरी की डंडियों या हल्के उबले हरे बीन्स के साथ आज़माएँ।","नमक न डालने पर प्रति सर्विंग सोडियम 121 mg होता है।"],["4 मांस","1/2 सब्ज़ी, कम पोटैशियम"]))
R.append(T(2979,"क्रैनबेरी ओटमील ब्रेकफास्ट कुकीज़","नाश्ते में कुकी तभी लें जब उसमें सेहतमंद सामग्री हो, जैसी किडनी-अनुकूल क्रैनबेरी ओटमील ब्रेकफास्ट कुकीज़ में होती है। सेब की प्यूरी, क्रैनबेरी, ओटमील और प्रोटीन पाउडर इन स्वाद से भरपूर कुकीज़ को नाश्ते का बेहतरीन विकल्प बना देते हैं।","12","1 कुकी",
["1/2 कप बिना नमक का मक्खन","1/2 कप दानेदार चीनी","1 बड़ा अंडा","1/4 कप मैदा","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1/2 छोटा चम्मच दालचीनी","1/4 छोटा चम्मच नमक","1.5 औंस वनीला व्हे प्रोटीन पाउडर","1 कप सेब की प्यूरी (एप्पलसॉस)","3 कप रोल्ड ओट्स","1/2 कप सूखी क्रैनबेरी"],
["मक्खन को कमरे के तापमान पर नरम होने के लिए बाहर रखें। ओवन को 350° F पर पहले से गरम करें। बेकिंग शीट पर बटर पेपर बिछाएँ।","इलेक्ट्रिक मिक्सर से मक्खन और चीनी को क्रीमी होने तक फेंटें। अंडा, मैदा, प्रोटीन पाउडर, वनीला एक्सट्रैक्ट, दालचीनी और नमक डालें। मिलाने के लिए चलाएँ।","सेब की प्यूरी डालकर मिलाएँ। ओट्स और क्रैनबेरी को धीरे से मिलाएँ।","कुकी के आटे को 1/4 कप के स्कूप से बेकिंग शीट पर रखें। हर कुकी को हल्का-सा दबाकर चपटा करें।","12 से 15 मिनट तक बेक करें, जब तक कुकीज़ सुनहरी भूरी न हो जाएँ लेकिन अंदर से नरम रहें।","कुकीज़ को बेकिंग शीट पर 5 मिनट ठंडा होने दें, फिर पूरी तरह ठंडा होने के लिए जाली पर रखें।"],
["कुकीज़ को वायुरोधी डिब्बे में रखें या अलग-अलग लपेटकर फ्रीज़ करें, ताकि जल्दी में नाश्ते के लिए तुरंत उठाया जा सके।","अलग-अलग ब्रांड के प्रोटीन पाउडर के स्कूप का आकार अलग होता है। एक स्कूप का वज़न जानने के लिए लेबल देखें, ताकि पता चले कि कितना डालना है, या तराज़ू से 1.5 औंस तौल लें।","ब्रेकफास्ट कुकीज़ का स्नैक के रूप में भी आनंद लें। 12 की जगह 24 छोटी कुकीज़ बनाने पर विचार करें।"],["1/2 मांस","1 स्टार्च","1 उच्च कैलोरी","1 वसा"]))
R.append(T(2980,"हॉर्सरैडिश मैरिनेड वाला फ्लैंक स्टेक","यह मैरिनेड स्टेक को नरम और रसीला रखता है और साथ ही भरपूर स्वाद भी देता है।","4","3 औंस",
["1 पाउंड फ्लैंक स्टेक","1/4 कप कैनोला तेल","लहसुन की 2 कलियाँ","2 बड़े चम्मच पिसी हुई साबुत हॉर्सरैडिश","1 बड़ा चम्मच दरदरी साबुत सरसों","1/2 छोटा चम्मच काली मिर्च","सजावट के लिए हरा प्याज़, वैकल्पिक"],
["फ्लैंक स्टेक को काँटे से गोदें ताकि स्टेक मैरिनेड का स्वाद सोख सके। दोनों तरफ हल्की काली मिर्च छिड़कें।","लहसुन को कुचलकर बारीक काटें। तेल, लहसुन, हॉर्सरैडिश और सरसों को ढक्कन वाले डिब्बे या डिस्पोज़ेबल बैग में फेंटकर मिलाएँ। स्टेक पर लगाएँ और मैरिनेड को मसलकर अच्छी तरह चढ़ाएँ। फ्रिज में कम से कम 2-4 घंटे रखें या सबसे अच्छे नतीजे के लिए रात भर रखें।","स्टेक को हर तरफ लगभग 5 मिनट तक ग्रिल करें, मनचाही पकावट तक और जब तक आंतरिक तापमान 165 डिग्री तक न पहुँच जाए। स्टेक को ग्रिल से निकालकर साफ कटिंग बोर्ड पर रखें और परोसने से पहले 5-10 मिनट आराम करने दें। इसके बजाय आप स्टोव पर ग्रिल पैन या स्किलेट का उपयोग कर सकते हैं।"],
["पहले से कटा हुआ और पतला स्टेक देखें। यदि वह पतला न हो, तो आप उसे प्लास्टिक रैप से ढककर पीटकर चपटा कर सकते हैं। इससे स्टेक जल्दी और समान रूप से पकता है।","ऐसी हॉर्सरैडिश और दरदरी सरसों चुनें जिसमें प्रति सर्विंग सोडियम सबसे कम हो।"],["3 प्रोटीन","1 वसा"]))
R.append(T(2982,"चिकन नींबू चावल सूप","इस चिकन और चावल के सूप में नींबू का हल्का-सा स्वाद है, जो इसे एक अनोखा स्वाद देता है।","6","1 कप",
["2 बड़े चम्मच ऑलिव ऑयल","1 बड़ा प्याज़","सेलरी की 1 डंठल","2 कप पका हुआ चिकन","लहसुन की 4 कलियाँ","1 बड़ी गाजर","8 कप पानी, बँटा हुआ","2 बड़े चम्मच वूस्टरशायर सॉस","2 बड़े चम्मच नींबू का रस","1/2 छोटा चम्मच नमक","3/4 छोटा चम्मच काली मिर्च","3/4 कप बिना पका चावल"],
["प्याज़, सेलरी और चिकन को काट लें। लहसुन को बारीक काटें और गाजर के टुकड़े करें। 5 क्वार्ट के सॉसपैन को मध्यम आँच पर गरम करें। उसमें ऑलिव ऑयल, प्याज़, सेलरी, लहसुन और गाजर डालें। लगभग 5 मिनट या सब्ज़ियाँ नरम होने तक भूनें।","चिकन और 4 कप पानी, वूस्टरशायर सॉस, नींबू का रस, नमक, काली मिर्च और चावल डालें। मध्यम आँच पर 15 मिनट या चावल पकने तक पकाएँ।","बचा हुआ 4 कप पानी डालें और गरम होने तक पकाते रहें।"],
["नमक को घटाकर 1/4 छोटा चम्मच करने पर प्रति सर्विंग सोडियम घटकर 211 mg हो जाएगा।","इस रेसिपी में आप ब्राउन या सफेद चावल का उपयोग कर सकते हैं। ब्राउन राइस को नरम होने में थोड़ा अधिक समय लग सकता है। ब्राउन राइस में पोटैशियम और फॉस्फोरस थोड़ा अधिक होता है, लेकिन शरीर इन सभी खनिजों को अवशोषित नहीं करता।"],["2 प्रोटीन","1 स्टार्च","1 सब्ज़ी, कम पोटैशियम"]))
R.append(T(2983,"कैलाब्रियन चिकन","यह चिकन थोड़ी गरमाहट और मिठास लाता है। चिकन को आम तौर पर बनाने के तरीके की जगह इसे आज़माएँ।","2","1 चिकन ब्रेस्ट या 2 चिकन कटलेट",
["1 नींबू","1 छोटा चम्मच कैलाब्रियन चिली पेस्ट","1 छोटा चम्मच शहद","2 चिकन ब्रेस्ट, बिना हड्डी और बिना त्वचा के","1/4 छोटा चम्मच पिसी काली मिर्च","2 बड़े चम्मच ऑलिव ऑयल","लहसुन की 2 कलियाँ","1 बड़ा चम्मच हेवी क्रीम"],
["नींबू का रस निचोड़ें। एक छोटे कटोरे में नींबू का रस, कैलाब्रियन चिली पेस्ट और शहद मिलाएँ। मिलाने के लिए चलाएँ।","हर चिकन ब्रेस्ट को बीच से आधा काटें ताकि आपके पास 2 पतले कटलेट रहें। दोनों तरफ काली मिर्च छिड़कें।","स्किलेट में मध्यम आँच पर ऑलिव ऑयल गरम करें। चिकन को पैन में डालें और हर तरफ 4-5 मिनट तक पकाएँ, जब तक आंतरिक तापमान 165 डिग्री तक न पहुँच जाए।","चिकन पक जाने पर लहसुन को बारीक काटकर पैन में डालें और खुशबू आने तक 1 मिनट पकाएँ। चिली का मिश्रण और हेवी क्रीम डालें और 1-2 मिनट और पकाएँ।","चिकन को प्लेट में रखें और बचा हुआ सॉस चिकन के ऊपर डालें।","चाहें तो चावल के साथ परोसें और आनंद लें! (प्रति सर्विंग पोषक तत्वों में चावल शामिल नहीं है)।"],
["कैलाब्रियन चिली पेस्ट तीखा हो सकता है। यदि आप तीखे भोजन के प्रति संवेदनशील हैं, तो चिली पेस्ट की मात्रा आधी कर सकते हैं।","यदि कैलाब्रियन चिली पेस्ट न मिले, तो उसकी जगह कटी हुई कैलाब्रियन मिर्च, कोई गाढ़ा चिली सॉस या लाल मिर्च के फ्लेक्स इस्तेमाल किए जा सकते हैं।"],["3-1/2 मांस/प्रोटीन","1 वसा"]))
R.append(T(2984,"आसान शहद-सरसों बाल्सेमिक विनेग्रेट","अगली बार जब आप सलाद बनाएँ, तो उसके ऊपर वाई यिन की आसान शहद-सरसों बाल्सेमिक विनेग्रेट डालने पर विचार करें। बाल्सेमिक सिरका, ऑलिव ऑयल, सरसों, शहद और काली मिर्च जैसी किडनी-अनुकूल सामग्री का यह मेल मीठा और तीखा स्वाद देता है, जो किसी भी सलाद को खास बना देता है।","8","2 बड़े चम्मच",
["1/2 कप बाल्सेमिक सिरका","1/3 कप ऑलिव ऑयल","2 बड़े चम्मच शहद","1 बड़ा चम्मच स्टोन ग्राउंड सरसों","1/4 छोटा चम्मच काली मिर्च"],
["सभी सामग्री एक जार में डालें। ढक्कन लगाकर ज़ोर से हिलाएँ, फिर तुरंत परोसें।","यदि ड्रेसिंग पहले से तैयार की गई है, तो परोसने से पहले अच्छी तरह हिलाएँ।"],
["इसे सलाद के पत्तों पर छिड़कें, या डुबोने के लिए छोटी सर्विंग डिश में रखें (ताकि ड्रेसिंग का ज़्यादा उपयोग न हो)।","बची हुई ड्रेसिंग को फ्रिज में एक सप्ताह तक रखें।","ब्रांड की तुलना करें और सबसे कम सोडियम वाली सरसों चुनें।"],["2 वसा","1/2 उच्च कैलोरी"]))
R.append(T(2986,"स्वीडिश मीटबॉल","स्वीडिश मीटबॉल की यह रेसिपी किडनी आहार को ध्यान में रखकर बनाई गई है। इस स्वादिष्ट व्यंजन को कम सोडियम के साथ बनाया जा सकता है और इसे पहले से भी तैयार किया जा सकता है।","24 सर्विंग","2 मीटबॉल",
["1/2 कप प्याज़","2 बड़े अंडे","3 पाउंड कीमा बनाया हुआ बीफ़","1 बड़ा चम्मच कैनोला तेल","1 कप ओटमील, बिना पका","1/2 कप कम सोडियम वाला बीफ़ शोरबा","1 बड़ा चम्मच सूखी सोआ (डिल)","2 बड़े चम्मच सूखा थाइम","1/4 छोटा चम्मच जायफल","1/4 छोटा चम्मच ऑलस्पाइस","1/4 छोटा चम्मच काली मिर्च","3 बड़े चम्मच बिना नमक का मक्खन","3 बड़े चम्मच मैदा","2 कप कम सोडियम (रिड्यूस्ड) वाला बीफ़ शोरबा","1/3 कप पानी"],
["ओवन को 375° F पर पहले से गरम करें।","प्याज़ काट लें। अंडे फेंट लें।","पहली 11 सामग्री को एक बड़े कटोरे में डालकर अच्छी तरह मिलाएँ।","1” के गोले बनाकर बेकिंग शीट पर रखें।","10 से 15 मिनट तक बेक करें, जब तक मीटबॉल अंदर तक पक न जाएँ।","सॉस बनाने के लिए एक बड़े सॉसपैन में मक्खन पिघलाएँ।","मैदा, रिड्यूस्ड-सोडियम शोरबा, बचा हुआ 1 बड़ा चम्मच सूखा थाइम और पानी डालें। मध्यम आँच पर गाढ़ा होने तक चलाते हुए पकाएँ।","मीटबॉल को सॉस में डालें और गरम रखने के लिए आँच कम कर दें, या ढके हुए वार्मिंग डिश या स्लो कुकर में धीमी आँच पर रखें।"],
["रिड्यूस्ड-सोडियम शोरबे में प्रति कप 450 से 500 mg सोडियम होता है। कम सोडियम वाले शोरबे में प्रति कप 140 mg या उससे कम सोडियम होता है।","मीटबॉल पहले से बनाकर फ्रिज में रखें। परोसने के लिए तैयार होने पर सामग्री को एक साथ गरम करें और वार्मिंग डिश में डालें।"],["1-1/2 मांस","1 वसा"]))
R.append(T(2987,"कम चीनी वाला गाजर केक","डायलिसिस वाले लोगों के लिए अपना खाना खुद पकाना और मिठाइयाँ खुद बेक करना डायलिसिस आहार को नियंत्रित करने में मदद करता है। कम चीनी वाले गाजर केक की यह रेसिपी आज़माएँ और रात के खाने के बाद की स्वादिष्ट मिठाई या दोपहर का नाश्ता बनाएँ, जो ज़रूर पसंद आएगा।","20","1 टुकड़ा 2-1/4\" x 2-1/2\"",
["2 कप मैदा","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच बेकिंग सोडा","1 छोटा चम्मच बेकिंग पाउडर","2 बड़े चम्मच दालचीनी","1-1/2 कप कैनोला तेल","1 कप Splenda® Sugar Blend for Baking","4 अंडे","3 कप गाजर, कद्दूकस की हुई","1/2 कप बिना नमक का मक्खन","8 औंस क्रीम चीज़","3/4 कप Splenda® No Calorie Sweetener, दानेदार","1 छोटा चम्मच वनीला"],
["ओवन को 350° F पर पहले से गरम करें।","9″ x 13″ के पैन में चिकनाई लगाएँ और हल्का आटा छिड़कें।","मैदा, नमक, बेकिंग सोडा, बेकिंग पाउडर और दालचीनी को एक साथ छान लें। एक तरफ रख दें।","तेल और Splenda® Sugar Blend for Baking को मिलाएँ। एक-एक करके अंडे डालें और हर अंडा डालने के बाद मिलाएँ।","धीरे-धीरे सूखी सामग्री डालें। अच्छी तरह मिलाएँ।","कद्दूकस की हुई गाजर को धीरे से मिलाएँ। बेकिंग पैन में डालें और 55 से 60 मिनट तक बेक करें, जब तक बीच में चुभाया गया टूथपिक साफ न निकले।","आइसिंग बनाने के लिए एक मिक्सिंग बाउल में मक्खन और क्रीम चीज़ मिलाएँ। मिक्सर से हल्का और फूला हुआ होने तक फेंटें।","फेंटते हुए धीरे-धीरे Splenda® दानेदार स्वीटनर डालें। वनीला डालकर अच्छी तरह मिलाएँ।","केक के अच्छी तरह ठंडा होने के बाद उस पर आइसिंग फैलाएँ।"],
["कम वसा वाले संस्करण के लिए, 1/2 कप कैनोला तेल की जगह 1/2 कप बिना मीठी सेब की प्यूरी डालें; अंडों की जगह 1 कप कम कोलेस्ट्रॉल वाला अंडा उत्पाद इस्तेमाल करें; कम कैलोरी वाला क्रीम चीज़ इस्तेमाल करें। (प्रति सर्विंग 250 कैलोरी, 18 ग्राम वसा)।","चाहें तो Splenda उत्पादों की जगह बराबर मात्रा में चीनी का उपयोग करें।","Splenda चार रूपों में उपलब्ध है: Splenda® Sugar Blend for Baking (आधा Splenda®, आधी चीनी), Splenda® Brown sugar Blend (आधा Splenda, आधी ब्राउन शुगर), Splenda® दानेदार स्वीटनर और Splenda® टेबलटॉप स्वीटनर। सबसे अच्छे नतीजों के लिए इस रेसिपी में बताए गए दो प्रकारों का ही उपयोग करें।"],["1 स्टार्च","1/2 सब्ज़ी, कम पोटैशियम","5 वसा"]))
R.append(T(2989,"प्यूर्टो रिको शैली के चिकन सींक","सींक पर भुना हुआ चिकन, जिसे अडोबो मसाले और अमरूद के बारबेक्यू सॉस के साथ तैयार किया गया है, टेबल पर बैठे सभी को ज़रूर पसंद आएगा।","8","1 सींक",
["2 पाउंड बिना हड्डी और बिना त्वचा की चिकन जाँघें","2 बड़े चम्मच अडोबो मसाला (DaVita.com की रेसिपी देखें)","1 बड़ा चम्मच सूखा ओरेगैनो","1 बड़ा चम्मच सफेद सिरका","2 बड़े चम्मच ऑलिव ऑयल","2 तेज पत्ते","1 कप अमरूद का बारबेक्यू सॉस (DaVita.com की रेसिपी देखें)","8 धातु या बाँस की सींकें"],
["चिकन की जाँघों को 2 इंच के निवाले जितने टुकड़ों में काटें। यदि बाँस की सींकों का उपयोग कर रहे हैं, तो उन्हें जलने से बचाने के लिए 1/2 घंटे पानी में भिगो दें।","अडोबो मसाला, ओरेगैनो, सिरका, ऑलिव ऑयल और तेज पत्ते को मिलाकर ज़िप वाले बैग में रखें।","चिकन को मैरिनेड में डालें। फ्रिज में कम से कम आधे घंटे से लेकर रात भर तक रखें।","ग्रिल को गरम करें और गरम होने पर जाली पर तेल लगाएँ।","चिकन को सींकों में पिरोएँ और गरम ग्रिल पर रखें। हर तरफ लगभग 5 मिनट तक सेकें।","पिंचोस पर अमरूद का बारबेक्यू सॉस या कोई अन्य कम सोडियम वाला बारबेक्यू सॉस लगाएँ और लगभग 4 मिनट और पकाएँ।"],
["चिकन के टुकड़े लगभग एक ही आकार के रखें ताकि वे समान रूप से पकें।","DaVita.com पर हमारा अमरूद बारबेक्यू सॉस और कम सोडियम वाले अन्य बारबेक्यू सॉस की रेसिपी देखें।","अपना खुद का कम सोडियम वाला अडोबो मसाला बनाएँ।"],["3 मांस"]))
